@Composable fun AssistantScreen(uid:String,tasks:List<Task>,save:(List<Task>)->Unit,plan:(Task)->Unit={}){val online=LocalOnlineAccess.current;val ctx=LocalContext.current;val scope=rememberCoroutineScope();var input by remember{mutableStateOf("")};var op by remember{mutableStateOf("Capturar tareas")};var selectedTask by remember{mutableStateOf("")};var busy by remember{mutableStateOf(false)};var confirm by remember{mutableStateOf(false)};var connect by remember{mutableStateOf(false)};var proposal by remember{mutableStateOf<AiProposal?>(null)};var draft by remember{mutableStateOf(emptyList<Task>())};var result by remember{mutableStateOf("")};var error by remember{mutableStateOf("")}
    fun execute(){val action=op;val chosen=selectedTask;val request=input;busy=true;proposal=null;draft=emptyList();result="";error="";scope.launch{try{val provider=AiConfig.provider(ctx,uid);val task=tasks.find{it.id==chosen};val p=when(action){"Capturar tareas"->provider.parseNaturalLanguage(request);"Desglosar tarea"->provider.suggestTaskBreakdown(task?:error("Selecciona tarea"));"Estimar esfuerzo"->provider.estimateEffort(task?:error("Selecciona tarea"));"Planificar tarea"->provider.suggestSchedule(task?:error("Selecciona tarea"));"Consultar agenda"->{result=provider.answerWithUserContext(request,tasks);null};else->{result=provider.summarizeTask(task?:error("Selecciona tarea"));null}};proposal=p;draft=if(action=="Capturar tareas")p?.tasks.orEmpty().map{it.copy(id=newId())}else p?.tasks?.firstOrNull()?.let{suggestion->listOf(if(action in listOf("Desglosar tarea","Planificar tarea"))task!!.copy(phases=suggestion.phases.ifEmpty{task.phases},minutes=if(suggestion.minutes>0)suggestion.minutes else task.minutes)else task!!.copy(minutes=suggestion.minutes))}.orEmpty()}catch(e:CancellationException){throw e}catch(e:Exception){error=e.localizedMessage?:"No se pudo interpretar"}finally{busy=false}}}
    Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Section("Asistente","Propuestas revisables. Nunca cambia tus datos sin confirmar.");GlassCard(tint=Lilac){Choice("Acción",listOf("Capturar tareas","Desglosar tarea","Estimar esfuerzo","Planificar tarea","Consultar agenda","Resumir tarea"),op,{it}){if(!busy){op=it;proposal=null;draft=emptyList();result=""}};if(op in listOf("Capturar tareas","Consultar agenda"))Field(input,{input=it},"Escribe tu petición",false)else Choice("Tarea",listOf("")+tasks.map{it.id},selectedTask,{id->tasks.find{it.id==id}?.title?:"Seleccionar"}){selectedTask=it};val ready=if(op in listOf("Capturar tareas","Consultar agenda"))input.isNotBlank()else selectedTask.isNotBlank();Button(enabled=ready&&!busy,onClick={if(!AiConfig.configured(ctx,uid))connect=true else confirm=true}){Text("Interpretar con Gemini")};if(busy)LinearProgressIndicator(Modifier.fillMaxWidth());if(error.isNotBlank())Text(error,color=MaterialTheme.colorScheme.error)};if(result.isNotBlank())GlassCard{Text(result)};proposal?.let{p->GlassCard{Text("Revisar propuesta",style=MaterialTheme.typography.titleLarge);(p.uncertainties+p.assumptions+p.suggestedQuestions).forEach{Text("• $it")}};draft.forEachIndexed{i,t->key(i){GlassCard{Field(t.title,{v->draft=draft.mapIndexed{j,x->if(i==j)x.copy(title=v)else x}},"Título");Field(t.description,{v->draft=draft.mapIndexed{j,x->if(i==j)x.copy(description=v)else x}},"Descripción",false);Text("${t.minutes} min · ${t.due.ifBlank{"Sin fecha"}}");t.phases.forEach{Text("• ${it.title} · ${it.minutes} min")};TextButton(onClick={draft=draft.filterIndexed{j,_->j!=i}}){Text("Descartar esta propuesta")}}}};Button(enabled=draft.isNotEmpty()&&draft.all{it.title.isNotBlank()},onClick={save(draft);proposal=null;draft=emptyList();result="Cambios guardados."}){Text("Confirmar y guardar")};if(draft.size==1&&op=="Planificar tarea")OutlinedButton(onClick={plan(draft.first());proposal=null;draft=emptyList()}){Text("Revisar horarios y planificar")};TextButton(onClick={proposal=null;draft=emptyList()}){Text("Descartar todo")}}}
    if(connect)PersonalGeminiDialog(uid){connect=false}
    if(confirm)Confirm("Enviar a Gemini","Se enviará ${if(op=="Consultar agenda")"tu pregunta y hasta diez tareas privadas sin contactos ni adjuntos" else if(op=="Capturar tareas")"el texto introducido" else "la tarea seleccionada sin contactos ni adjuntos"} directamente a Gemini con tu clave personal. No se enviarán otras secciones.",{confirm=false},{execute()})
}
